#include <windows.h>
#include "profile_store.h"
#include <string.h>
int nflstreet_option_load(const char*path,uint32_t*v){if(!path||!*path||!v)return 0;HANDLE f=CreateFileA(path,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(f==INVALID_HANDLE_VALUE)return GetLastError()==ERROR_FILE_NOT_FOUND?2:0;uint8_t b[196];LARGE_INTEGER size;DWORD got=0;int ok=GetFileSizeEx(f,&size)&&size.QuadPart==196&&ReadFile(f,b,sizeof b,&got,NULL)&&got==sizeof b;int closed=CloseHandle(f);return ok&&closed&&nflstreet_option_decode(b,sizeof b,v);}
int nflstreet_option_save(const char*path,const uint32_t*v){if(!path||!*path||!v||strlen(path)>=MAX_PATH)return 0;uint8_t b[196];if(!nflstreet_option_encode(v,b))return 0;char directory[MAX_PATH],temp[MAX_PATH];strcpy(directory,path);char*slash=NULL;for(char*p=directory;*p;++p)if(*p=='/'||*p=='\\')slash=p;if(slash){slash[1]=0;}else strcpy(directory,".");if(!GetTempFileNameA(directory,"nso",0,temp))return 0;HANDLE f=CreateFileA(temp,GENERIC_WRITE,0,NULL,TRUNCATE_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);if(f==INVALID_HANDLE_VALUE){DeleteFileA(temp);return 0;}DWORD wrote=0;int ok=WriteFile(f,b,sizeof b,&wrote,NULL)&&wrote==sizeof b&&FlushFileBuffers(f);int closed=CloseHandle(f);if(ok&&closed)ok=MoveFileExA(temp,path,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);else ok=0;if(!ok)DeleteFileA(temp);return ok;}
